def set_language(lang: str) -> None:
    global _CURRENT_LANG
    valid_codes = {code for code, _, _, _ in SUPPORTED_LANGUAGES}
    _CURRENT_LANG = lang if lang in valid_codes else "en"
    if QApplication is not None and Qt is not None:
        app = QApplication.instance()
        if app is not None:
            app.setLayoutDirection(
                Qt.LayoutDirection.RightToLeft if _CURRENT_LANG in RTL_LANGS else Qt.LayoutDirection.LeftToRight
            )


def get_language() -> str:
    return _CURRENT_LANG


def is_rtl() -> bool:
    return _CURRENT_LANG in RTL_LANGS


def get_lang_font_family() -> str:
    for code, _, _, fam in SUPPORTED_LANGUAGES:
        if code == _CURRENT_LANG:
            return fam
    return "Tajawal"


def fmt_num(val: int | float | str) -> str:
    s = str(val)
    if _CURRENT_LANG in ("ar", "ur"):
        return s.translate(_EASTERN_ARABIC_DIGITS)
    if _CURRENT_LANG == "fa":
        return s.translate(_PERSIAN_DIGITS)
    return s


def t(key: str, default: str | None = None) -> str:
    entry = TRANSLATIONS.get(key)
    if not entry:
        return default if default is not None else key
    return entry.get(_CURRENT_LANG, entry.get("en", key))


def tp(key: str, **kwargs: object) -> str:
    base = t(key)
    try:
        return base.format(**kwargs)
    except Exception:
        return base


def tl(ar_text: str, en_text: str) -> str:
    return ar_text if _CURRENT_LANG in RTL_LANGS else en_text


def bidi_text(text: str) -> str:
    if not text:
        return ""
    return (RLM if is_rtl() else LRM) + text


def ltr_value(val: str) -> str:
    return f"{LRM}{val}{LRM}"


